using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var mlContext = new MLContext(seed: 0);
var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

// Fallback for running from project directory
if (!File.Exists(dataPath))
    dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "customers.csv");

ITransformer? trainedModel = null;

app.MapPost("/train", () =>
{
    var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

    var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
        .Append(mlContext.Transforms.Concatenate("Features",
            nameof(CustomerData.Age),
            nameof(CustomerData.Income),
            "RegionEncoded",
            nameof(CustomerData.PurchaseHistory)))
        .Append(mlContext.Transforms.NormalizeMinMax("Features"))
        .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
            labelColumnName: nameof(CustomerData.Churned),
            featureColumnName: "Features"));

    trainedModel = pipeline.Fit(dataView);
    mlContext.Model.Save(trainedModel, dataView.Schema, modelPath);

    // Evaluate on training data
    var predictions = trainedModel.Transform(dataView);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: nameof(CustomerData.Churned));

    return Results.Ok(new
    {
        Message = "Model trained and saved.",
        Accuracy = metrics.Accuracy,
        F1Score = metrics.F1Score,
        AUC = metrics.AreaUnderRocCurve
    });
});

app.MapPost("/predict", (CustomerInput input) =>
{
    if (trainedModel is null)
    {
        if (!File.Exists(modelPath))
            return Results.BadRequest(new { Error = "Model not trained yet. POST to /train first." });
        trainedModel = mlContext.Model.Load(modelPath, out _);
    }

    var engine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(trainedModel);

    var data = new CustomerData
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory
    };

    var result = engine.Predict(data);
    return Results.Ok(new
    {
        WillChurn = result.PredictedLabel,
        Probability = result.Probability,
        Score = result.Score
    });
});

app.MapGet("/", () => "Churn Predictor API — POST /train then POST /predict");
app.Run();

// --- Data models ---

public class CustomerData
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = string.Empty;
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4), ColumnName("Churned")]
    public bool Churned { get; set; }
}

public class CustomerInput
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string Region { get; set; } = string.Empty;
    public float PurchaseHistory { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")] public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
    public float Score { get; set; }
}

